def factorial_recursive(n):
    """Beregner fakultetet af n ved hjælp af rekursion."""
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input skal være et ikke-negativt heltal.")

    # Base case
    if n == 0:
        return 1

    # Recursive step
    return n * factorial_recursive(n - 1)

# Example usage:
# print(factorial_recursive(5))  # Returns 120
# print(factorial_recursive(0))  # Returns 1

python
def factorial_recursive(n):
    """
    Beregner fakultetet af et ikke-negativt heltal n ved hjælp af rekursion.
    Fakultetet af 0 er defineret som 1.

    Raises:
        ValueError: Hvis n er negativt.
    """
    if n < 0:
        raise ValueError("Fakultet er ikke defineret for negative tal.")
    elif n == 0:
        return 1
    else:
        return n * factorial_recursive(n - 1)

# Eksempel på brug:
# print(factorial_recursive(5)) # Output: 120

