def fibonacci_recursive(n):
    """Beregner det n'te Fibonacci-tal ved hjælp af rekursion.
    Returnerer 0 for ikke-positive input.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

